import { TrendingDown, TrendingUp } from "lucide-react";

import { Marquee } from "@/components/shadcn-space/animations/marquee";
import { cn } from "@/lib/utils";

type Stock = {
  symbol: string;
  name: string;
  price: number;
  change: number;
  logoClass: string;
};

const stocks: Stock[] = [
  {
    symbol: "AAPL",
    name: "Apple",
    price: 227.48,
    change: 1.24,
    logoClass: "bg-blue-500",
  },
  {
    symbol: "MSFT",
    name: "Microsoft",
    
    price: 418.92,
    change: -0.63,
    logoClass: "bg-sky-400",
  },
  {
    symbol: "NVDA",
    name: "NVIDIA",
    price: 131.76,
    change: 3.41,
    logoClass: "bg-teal-400",
  },
  {
    symbol: "TSLA",
    name: "Tesla",
    price: 248.5,
    change: -2.18,
    logoClass: "bg-red-500",
  },
  {
    symbol: "AMZN",
    name: "Amazon",
    price: 186.3,
    change: 0.87,
    logoClass: "bg-orange-400",
  },
  {
    symbol: "GOOGL",
    name: "Alphabet",
    price: 165.12,
    change: 1.05,
    logoClass: "bg-amber-300",
  },
  {
    symbol: "META",
    name: "Meta",
    price: 512.74,
    change: -1.32,
    logoClass: "bg-blue-500",
  },
  {
    symbol: "NFLX",
    name: "Netflix",
    price: 689.05,
    change: 2.76,
    logoClass: "bg-sky-400",
  },
];

const StockItem = ({ symbol, name, price, change, logoClass }: Stock) => {
  const isUp = change >= 0;
  const TrendIcon = isUp ? TrendingUp : TrendingDown;

  return (
    <div className="flex items-center gap-3 px-6">
      <div
        className={cn(
          "flex size-9 shrink-0 items-center justify-center rounded-full text-sm font-bold text-white",
          logoClass,
        )}
      >
        {symbol.charAt(0)}
      </div>
      <p className="text-sm font-medium text-foreground">{name}</p>
      <p className="text-sm text-muted-foreground">${price.toFixed(2)}</p>
      <p
        className={cn(
          "flex items-center gap-1 text-sm font-medium",
          isUp
            ? "text-emerald-600 dark:text-emerald-400"
            : "text-red-600 dark:text-red-400",
        )}
      >
        <TrendIcon className="size-4" aria-hidden="true" />
        {isUp ? "+" : ""}
        {change.toFixed(2)}%
      </p>
    </div>
  );
};

export default function TrendingStocksMarqueeDemo() {
  return (
    <div className="w-full overflow-hidden rounded-xl border border-border bg-card">
      <Marquee pauseOnHover className="py-4 [--duration:30s] [--gap:0rem]">
        {stocks.map((stock) => (
          <StockItem key={stock.symbol} {...stock} />
        ))}
      </Marquee>
    </div>
  );
}

import { ComponentPropsWithoutRef } from "react";
 
import { cn } from "@/lib/utils";
 
interface MarqueeProps extends ComponentPropsWithoutRef<"div"> {
  className?: string;
  /**
   * Whether to reverse the animation direction
   * @default false
   */
  reverse?: boolean;
  /**
   * Whether to pause the animation on hover
   * @default false
   */
  pauseOnHover?: boolean;
  /**
   * Content to be displayed in the marquee
   */
  children: React.ReactNode;
  /**
   * Whether to animate vertically instead of horizontally
   * @default false
   */
  vertical?: boolean;
  /**
   * Number of times to repeat the content
   * @default 4
   */
  repeat?: number;
}
 
export function Marquee({
  className,
  reverse = false,
  pauseOnHover = false,
  children,
  vertical = false,
  repeat = 4,
  ...props
}: MarqueeProps) {
  return (
    <>
      <style>
        {`
          @keyframes marquee {
            from {
              transform: translateX(0);
            }
            to {
              transform: translateX(calc(-100% - var(--gap)));
            }
          }
 
          @keyframes marquee-vertical {
            from {
              transform: translateY(0);
            }
            to {
              transform: translateY(calc(-100% - var(--gap)));
            }
          }
 
          @keyframes scroll {
            to {
              transform: translate(calc(-50% - 0.5rem));
            }
          }
 
          .animate-marquee {
            animation: marquee var(--duration) linear infinite;
          }
 
          .animate-marquee-vertical {
            animation: marquee-vertical var(--duration) linear infinite;
          }
 
          .animate-reverse {
            animation-direction: reverse !important;
          }
 
          .pause-on-hover:hover .animate-marquee,
          .pause-on-hover:hover .animate-marquee-vertical {
            animation-play-state: paused !important;
          }
 
          .animate-scroll {
            animation: scroll var(--animation-duration, 40s) var(--animation-direction, forwards) linear infinite;
          }
        `}
      </style>
      <div
        {...props}
        className={cn(
          "group flex gap-(--gap) overflow-hidden p-2 [--duration:40s] [--gap:1rem]",
          {
            "flex-row": !vertical,
            "flex-col": vertical,
            "pause-on-hover": pauseOnHover,
          },
          className,
        )}
      >
        {Array(repeat)
          .fill(0)
          .map((_, i) => (
            <div
              key={i}
              className={cn("flex shrink-0 justify-around gap-(--gap)", {
                "animate-marquee flex-row": !vertical,
                "animate-marquee-vertical flex-col": vertical,
                "animate-reverse": reverse,
              })}
            >
              {children}
            </div>
          ))}
      </div>
    </>
  );
}
